const SEEN_KEY = "splash-seen";
const VISIBLE_MS = 2900;
const FADE_MS = 500;

function hasSeenSplash() {
  try {
    return sessionStorage.getItem(SEEN_KEY) === "1";
  } catch {
    return false;
  }
}

function SplashScreen() {
  const [phase, setPhase] = useState(() => (hasSeenSplash() ? "done" : "show"));

  useEffect(() => {
    if (phase === "done") return undefined;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const fadeTimer = setTimeout(() => setPhase("fade"), reduced ? 400 : VISIBLE_MS);
    const doneTimer = setTimeout(() => {
      try {
        sessionStorage.setItem(SEEN_KEY, "1");
      } catch {
        /* ignore */
      }
      setPhase("done");
    }, (reduced ? 400 : VISIBLE_MS) + FADE_MS);
    return () => {
      clearTimeout(fadeTimer);
      clearTimeout(doneTimer);
    };
  }, [phase === "done"]);

  if (phase === "done") return null;

  return (
    <div
      aria-hidden="true"
      className="fixed inset-0 z-[9999] flex items-center justify-center bg-background-dark"
      style={{
        opacity: phase === "fade" ? 0 : 1,
        transition: `opacity ${FADE_MS}ms ease-out`,
        pointerEvents: phase === "fade" ? "none" : "auto",
      }}
    >
      <svg viewBox="0 0 1024 1024" className="splash-logo-svg" xmlns="http://www.w3.org/2000/svg">
        <path className="splash-logo" pathLength="1" fillRule="evenodd" d={LOGO_PATH} />
      </svg>
    </div>
  );
}

export default SplashScreen;
